ALTER TABLE software_contracts ADD CONSTRAINT software_contracts_quantity_check CHECK (purchased_quantity > 0);
ALTER TABLE software_contracts ADD CONSTRAINT software_contracts_license_type_check CHECK (license_type IN ('user', 'device', 'concurrent'));
ALTER TABLE software_contracts ADD CONSTRAINT software_contracts_date_check CHECK ((ends_on IS NULL OR ends_on >= starts_on) AND (renews_on IS NULL OR renews_on >= starts_on));
ALTER TABLE software_license_terms ADD CONSTRAINT software_license_terms_counting_unit_check CHECK (counting_unit IN ('employee', 'asset', 'concurrent'));
ALTER TABLE software_license_terms ADD CONSTRAINT software_license_terms_positive_check CHECK ((users_per_license IS NULL OR users_per_license > 0) AND (devices_per_user IS NULL OR devices_per_user > 0) AND (concurrent_limit IS NULL OR concurrent_limit > 0));
ALTER TABLE software_license_terms ADD CONSTRAINT software_license_terms_evidence_check CHECK (evidence_status IN ('confirmed', 'unverified'));
ALTER TABLE software_license_keys ADD CONSTRAINT software_license_keys_activation_check CHECK (activation_limit IS NULL OR activation_limit > 0);
ALTER TABLE software_assignments ADD CONSTRAINT software_assignments_target_check CHECK ((employee_id IS NULL) <> (asset_id IS NULL));
ALTER TABLE software_assignments ADD CONSTRAINT software_assignments_dates_check CHECK ((planned_release_on IS NULL OR planned_release_on >= assigned_on) AND (released_on IS NULL OR released_on >= assigned_on) AND (deactivated_on IS NULL OR released_on IS NOT NULL));
CREATE UNIQUE INDEX software_assignments_active_employee_key ON software_assignments (contract_id, employee_id) WHERE employee_id IS NOT NULL AND released_on IS NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX software_assignments_active_asset_key ON software_assignments (contract_id, asset_id) WHERE asset_id IS NOT NULL AND released_on IS NULL AND deleted_at IS NULL;

