-- Existing databases receive the catalog, while grants remain an explicit role decision.
INSERT INTO permissions (name)
SELECT 'Operation: ' || code FROM unnest(ARRAY[
  'software.read', 'software.manage', 'software.keys.read', 'software.keys.write',
  'software.products.create', 'software.products.update',
  'software.contracts.create', 'software.contracts.update',
  'software.keys.create', 'software.keys.update', 'software.keys.reveal',
  'software.assignments.create', 'software.assignments.release'
]) AS code
WHERE EXISTS (SELECT 1 FROM roles)
ON CONFLICT (name) DO NOTHING;

INSERT INTO permission_operations (operation, permission_id)
SELECT substring(p.name FROM 12), p.id FROM permissions p
WHERE p.name LIKE 'Operation: software.%' AND p.deleted_at IS NULL
ON CONFLICT (operation) DO NOTHING;

INSERT INTO role_permissions (role_id, permission_id, scope_type)
SELECT r.id, po.permission_id, 'global'
FROM roles r CROSS JOIN permission_operations po
WHERE r.default_key = 'system_administrator' AND r.deleted_at IS NULL
  AND po.operation LIKE 'software.%' AND po.deleted_at IS NULL
ON CONFLICT (role_id, permission_id) DO NOTHING;
